// Valida y repara los datos que vienen de Google Sheets.
//
// Por que la reparacion: al subir el CSV, Sheets en configuracion regional
// argentina lee el punto como separador de miles, asi que 0.2923 se
// convierte en 2923. La columna prevalencia_pct (un decimal) no sufre ese
// problema, asi que se reconstruye la prevalencia a partir de ella.

const COLUMNAS = ['indicador', 'anio', 'corte_tipo', 'corte_valor', 'n', 'prevalencia_pct'];
const minimas = parseInt($('Parametros').first().json.filas_minimas, 10) || 100;

const filas = $input.all().map(i => i.json);

if (filas.length < minimas) {
  throw new Error(`Llegaron ${filas.length} filas y se esperaban al menos ${minimas}. Revisar la pestana de origen.`);
}

const faltan = COLUMNAS.filter(c => !(c in filas[0]));
if (faltan.length) {
  throw new Error('Faltan columnas en la planilla de origen: ' + faltan.join(', '));
}

// Convierte un numero que puede venir con formato local (1.234,5 o 1234.5)
function aNumero(v) {
  if (typeof v === 'number') return v;
  if (v === null || v === undefined || v === '') return NaN;
  let s = String(v).trim();
  if (s.includes(',')) s = s.replace(/\./g, '').replace(',', '.');
  return Number(s);
}

const limpias = [];
const reparadas = [];
const descartadas = [];

for (const f of filas) {
  const pct = aNumero(f.prevalencia_pct);
  const n = aNumero(f.n);
  const anio = aNumero(f.anio);
  let prev = aNumero(f.prevalencia);

  // Si la prevalencia no quedo entre 0 y 1, se reconstruye desde el porcentaje
  if (!(prev >= 0 && prev <= 1)) {
    if (pct >= 0 && pct <= 100) {
      prev = pct / 100;
      reparadas.push(f.indicador + ' / ' + f.corte_valor + ' / ' + f.anio);
    } else {
      descartadas.push({ fila: f, motivo: 'prevalencia y porcentaje invalidos' });
      continue;
    }
  }

  const problema =
    !isFinite(n) || n < 30 ? 'muestra menor a 30'
    : !isFinite(anio) || anio < 2000 || anio > 2100 ? 'anio invalido'
    : !String(f.indicador || '').trim() ? 'indicador vacio'
    : null;

  if (problema) {
    descartadas.push({ fila: f, motivo: problema });
    continue;
  }

  limpias.push({
    json: {
      indicador: String(f.indicador).trim(),
      anio: Math.round(anio),
      corte_tipo: String(f.corte_tipo || '').trim(),
      corte_valor: String(f.corte_valor || '').trim(),
      n: Math.round(n),
      prevalencia: Math.round(prev * 10000) / 10000,
      prevalencia_pct: Math.round(prev * 1000) / 10,
      fuente: f.fuente || 'ENFR - INDEC',
      actualizado: new Date().toISOString().slice(0, 10)
    }
  });
}

if (!limpias.length) {
  throw new Error('Ninguna fila paso el control de calidad.');
}

console.log(`Validadas ${limpias.length} filas | reparadas ${reparadas.length} | descartadas ${descartadas.length}`);
if (descartadas.length) {
  console.log('Descartadas:', JSON.stringify(descartadas.slice(0, 10), null, 2));
}

return limpias;

// Resumen para la weekly y para el informe del capstone.

const filas = $input.all().map(i => i.json);

const porIndicador = {};
for (const f of filas) {
  if (!porIndicador[f.indicador]) porIndicador[f.indicador] = 0;
  porIndicador[f.indicador] += 1;
}

const anios = filas.map(f => f.anio);
const tipos = [...new Set(filas.map(f => f.corte_tipo))];

// Ranking de provincias con mayor hipertension en el ultimo anio
const htaProv = filas.filter(f => f.indicador === 'hta' && f.corte_tipo === 'provincia');
const ultimo = htaProv.length ? Math.max(...htaProv.map(f => f.anio)) : null;
const top5 = htaProv
  .filter(f => f.anio === ultimo)
  .sort((a, b) => b.prevalencia - a.prevalencia)
  .slice(0, 5)
  .map(f => `${f.corte_valor} ${f.prevalencia_pct}%`);

// Evolucion del total pais
const total = filas.filter(f => f.corte_tipo === 'total');
const evolucion = {};
for (const f of total) {
  if (!evolucion[f.indicador]) evolucion[f.indicador] = {};
  evolucion[f.indicador][f.anio] = f.prevalencia_pct;
}

return [{
  json: {
    filas_publicadas: filas.length,
    filas_por_indicador: porIndicador,
    cortes_disponibles: tipos,
    anio_min: Math.min(...anios),
    anio_max: Math.max(...anios),
    top5_provincias_hta: top5,
    anio_del_ranking: ultimo,
    evolucion_total_pais: evolucion,
    corrido_el: new Date().toISOString()
  }
}];
